INSERT OR IGNORE INTO edu_contents (id, slug, title, category, summary, body_md, source_name, source_url, status, published_at)
VALUES ('art-ckg-2026','cek-kesehatan-gratis-2026-yang-baru','Cek Kesehatan Gratis 2026: Target Lebih Besar, Ada Pengobatan Lanjutan','program','Program Cek Kesehatan Gratis (CKG) Kemenkes berjalan sejak 10 Februari 2025. Pada 2026 sasarannya naik menjadi 46% penduduk, layanan diperluas ke pustu, posyandu, dan tempat kerja, dan hasil pemeriksaan kini ditindaklanjuti pengobatan gratis untuk kondisi tertentu.','Cek Kesehatan Gratis (CKG) adalah program Kementerian Kesehatan yang memberikan pemeriksaan kesehatan tanpa biaya di puskesmas dan fasilitas kesehatan tingkat pertama. Program ini berjalan sejak 10 Februari 2025 dan pada tahun pertamanya menjangkau sekitar 70,8 juta warga, atau 24,9% penduduk Indonesia.

Untuk 2026, Kemenkes menargetkan 46% penduduk menerima CKG. Hingga pertengahan 2026, Kemenkes mencatat lebih dari 89 juta warga telah memanfaatkan layanan ini. Agar lebih mudah dijangkau, layanan diperluas tidak hanya di puskesmas, tetapi juga di puskesmas pembantu (pustu), posyandu, fasilitas kesehatan tingkat pertama lain, perkantoran, dan komunitas — petugas yang mendatangi warga, bukan sebaliknya.

Perubahan penting mulai 2026: hasil pemeriksaan tidak berhenti pada lembar hasil. Kemenkes menerapkan tindak lanjut berupa pengobatan gratis bagi peserta dengan kondisi tertentu, antara lain hipertensi dan diabetes, agar risiko yang ditemukan segera tertangani dan terhubung dengan layanan Jaminan Kesehatan Nasional (JKN).

Di Lampung, CKG dapat dimanfaatkan di puskesmas di seluruh 15 kabupaten/kota. Bawalah kartu identitas dan, bila ada, kartu BPJS Kesehatan. Hasil CKG adalah hasil skrining dan pemeriksaan awal; bila ditemukan kelainan, tenaga kesehatan akan mengarahkan pemeriksaan atau pengobatan lanjutan. Anda juga dapat mencatat hasil pengukuran dari CKG ke SIGERSEHAT agar trennya terpantau dari waktu ke waktu.','Kementerian Kesehatan RI','https://kemkes.go.id','published','2026-11-25 01:30:00');
INSERT OR IGNORE INTO ai_sources (id, title, publisher, url, content_text, topic_tags, status)
VALUES ('src-art-ckg-2026','Cek Kesehatan Gratis 2026: Target Lebih Besar, Ada Pengobatan Lanjutan','Kementerian Kesehatan RI','https://kemkes.go.id','Cek Kesehatan Gratis (CKG) adalah program Kementerian Kesehatan yang memberikan pemeriksaan kesehatan tanpa biaya di puskesmas dan fasilitas kesehatan tingkat pertama, berjalan sejak 10 Februari 2025. Tahun pertama menjangkau sekitar 70,8 juta warga (24,9% penduduk). Target 2026 adalah 46% penduduk; hingga pertengahan 2026 lebih dari 89 juta warga telah memanfaatkan CKG menurut Kemenkes. Layanan 2026 diperluas ke puskesmas pembantu (pustu), posyandu, fasilitas kesehatan tingkat pertama lain, perkantoran, dan komunitas. Mulai 2026 hasil CKG ditindaklanjuti pengobatan gratis untuk kondisi tertentu, antara lain hipertensi dan diabetes, terhubung dengan JKN. Di Lampung CKG tersedia di puskesmas seluruh 15 kabupaten/kota; bawa kartu identitas dan kartu BPJS bila ada. Hasil CKG adalah skrining dan pemeriksaan awal, bukan diagnosis akhir.','program, ckg, skrining, pencegahan','active');
