INSERT OR IGNORE INTO edu_references (id, content_id, title, publisher, url, sort_order) VALUES ('ref-art-ckg-2026-2','art-ckg-2026','Ayo Sehat — portal edukasi Kemenkes RI','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id',2);

INSERT OR IGNORE INTO edu_contents (id, slug, title, category, summary, body_md, source_name, source_url, status, published_at)
VALUES ('art-aktivitas-fisik','aktivitas-fisik-150-menit-seminggu','Aktivitas Fisik: 150 Menit Seminggu yang Menyelamatkan','umum','WHO menganjurkan orang dewasa beraktivitas fisik intensitas sedang 150–300 menit per minggu. Kemenkes menyederhanakannya: bergerak aktif minimal 30 menit setiap hari.','Kurang bergerak adalah faktor risiko utama penyakit tidak menular seperti hipertensi, diabetes, penyakit jantung, dan obesitas. Kabar baiknya, aktivitas fisik tidak harus berupa olahraga berat di pusat kebugaran.

WHO menganjurkan orang dewasa melakukan aktivitas fisik intensitas sedang selama 150 sampai 300 menit per minggu, atau intensitas tinggi 75 sampai 150 menit per minggu, ditambah latihan penguatan otot dua kali seminggu. Kementerian Kesehatan menyederhanakan pesan ini menjadi: beraktivitas fisik minimal 30 menit setiap hari.

Intensitas sedang berarti napas lebih cepat dari biasa tetapi masih bisa berbicara, misalnya jalan cepat, bersepeda santai, berenang, atau berkebun. Aktivitas harian seperti naik tangga, berjalan ke warung, dan pekerjaan rumah tangga yang aktif juga terhitung. Bagi pekerja kantoran, bangun dan bergeraklah beberapa menit setiap satu jam duduk.

Mulailah bertahap bila selama ini jarang bergerak: 10 menit jalan kaki setelah makan sudah merupakan awal yang baik, lalu tambah durasinya. Bila Anda memiliki penyakit jantung, sesak, atau nyeri dada saat beraktivitas, konsultasikan dulu ke dokter sebelum memulai program latihan. Hentikan aktivitas dan segera cari pertolongan bila muncul nyeri dada atau sesak berat.','Organisasi Kesehatan Dunia (WHO)','https://www.who.int','published','2026-11-25 01:29:00');
INSERT OR IGNORE INTO ai_sources (id, title, publisher, url, content_text, topic_tags, status)
VALUES ('src-art-aktivitas-fisik','Aktivitas Fisik: 150 Menit Seminggu yang Menyelamatkan','Organisasi Kesehatan Dunia (WHO)','https://www.who.int','WHO menganjurkan orang dewasa beraktivitas fisik intensitas sedang 150 sampai 300 menit per minggu, atau intensitas tinggi 75 sampai 150 menit per minggu, ditambah penguatan otot dua kali seminggu. Kemenkes menyederhanakannya menjadi aktivitas fisik minimal 30 menit setiap hari. Intensitas sedang contohnya jalan cepat, bersepeda santai, berenang, berkebun; napas lebih cepat tetapi masih bisa berbicara. Kurang bergerak adalah faktor risiko hipertensi, diabetes, penyakit jantung, dan obesitas. Mulai bertahap, misalnya jalan kaki 10 menit setelah makan. Nyeri dada atau sesak berat saat beraktivitas adalah tanda bahaya: hentikan aktivitas dan cari pertolongan segera.','aktivitas fisik, gaya hidup, pencegahan, ptm','active');
INSERT OR IGNORE INTO edu_references (id, content_id, title, publisher, url, sort_order) VALUES ('ref-art-aktivitas-fisik-1','art-aktivitas-fisik','Physical activity — fact sheet WHO','Organisasi Kesehatan Dunia (WHO)','https://www.who.int',1);
INSERT OR IGNORE INTO edu_references (id, content_id, title, publisher, url, sort_order) VALUES ('ref-art-aktivitas-fisik-2','art-aktivitas-fisik','GERMAS dan aktivitas fisik — Kemenkes RI','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id',2);

INSERT OR IGNORE INTO edu_contents (id, slug, title, category, summary, body_md, source_name, source_url, status, published_at)
VALUES ('art-diabetes','diabetes-melitus-mengenali-gula-darahmu','Diabetes Melitus: Mengenali Gula Darahmu Sejak Dini','ptm','Di Lampung, 1,2% penduduk terdiagnosis diabetes menurut SKI 2023 — dan seperti hipertensi, banyak kasus belum terdeteksi. Kenali tanda-tandanya dan periksa gula darahmu secara berkala.','Diabetes melitus adalah kondisi kadar gula darah tinggi yang berlangsung lama karena tubuh tidak menghasilkan cukup insulin atau tidak dapat memakainya dengan baik. Menurut Survei Kesehatan Indonesia (SKI) 2023, prevalensi diabetes terdiagnosis dokter di Lampung adalah 1,2% pada semua umur. Seperti hipertensi, angka sebenarnya diperkirakan lebih besar karena banyak penderita belum memeriksakan diri.

Tanda klasik diabetes yang perlu diwaspadai: sering buang air kecil terutama malam hari, sering haus, sering lapar, berat badan turun tanpa sebab jelas, luka lambat sembuh, kesemutan pada tangan dan kaki, serta pandangan kabur. Bila mengalami tanda-tanda ini, periksakan gula darah ke puskesmas. Pemeriksaan dapat berupa gula darah sewaktu, gula darah puasa, atau HbA1c, dan penegakan diagnosis adalah kewenangan dokter.

Faktor risiko diabetes meliputi riwayat keluarga, kelebihan berat badan terutama lemak perut, kurang aktivitas fisik, dan riwayat gula darah tinggi saat hamil. Risiko dapat diperkirakan sejak dini, misalnya dengan kuesioner FINDRISC yang juga tersedia pada skrining di platform ini.

Pencegahan dan pengendalian diabetes bertumpu pada pola hidup: batasi gula maksimal 4 sendok makan per hari, perbanyak sayur dan serat, beraktivitas fisik minimal 30 menit sehari, jaga berat badan, dan periksa gula darah berkala — tersedia juga lewat program Cek Kesehatan Gratis di puskesmas. Bagi yang sudah terdiagnosis, minum obat teratur sesuai resep dan kontrol berkala sangat penting untuk mencegah komplikasi pada mata, ginjal, saraf, dan jantung.','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id','published','2026-11-25 01:28:00');
INSERT OR IGNORE INTO ai_sources (id, title, publisher, url, content_text, topic_tags, status)
VALUES ('src-art-diabetes','Diabetes Melitus: Mengenali Gula Darahmu Sejak Dini','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id','Diabetes melitus adalah kadar gula darah tinggi berkepanjangan. Prevalensi diabetes terdiagnosis dokter di Lampung adalah 1,2% (SKI 2023, semua umur). Tanda klasik: sering buang air kecil terutama malam hari, sering haus, sering lapar, berat badan turun tanpa sebab, luka lambat sembuh, kesemutan, pandangan kabur. Pemeriksaan gula darah dapat berupa gula darah sewaktu, puasa, atau HbA1c di puskesmas; diagnosis adalah kewenangan dokter. Faktor risiko: riwayat keluarga, kelebihan berat badan dan lemak perut, kurang aktivitas fisik, riwayat gula darah tinggi saat hamil. Pencegahan: batasi gula maksimal 4 sendok makan per hari, perbanyak sayur dan serat, aktivitas fisik minimal 30 menit sehari, jaga berat badan, periksa gula darah berkala termasuk lewat Cek Kesehatan Gratis. Risiko diabetes dapat diperkirakan dengan kuesioner FINDRISC.','diabetes, gula darah, ptm, skrining','active');
INSERT OR IGNORE INTO edu_references (id, content_id, title, publisher, url, sort_order) VALUES ('ref-art-diabetes-1','art-diabetes','Diabetes melitus — materi edukasi Kemenkes RI','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id',1);
INSERT OR IGNORE INTO edu_references (id, content_id, title, publisher, url, sort_order) VALUES ('ref-art-diabetes-2','art-diabetes','Survei Kesehatan Indonesia (SKI) 2023 Dalam Angka','BKPK Kemenkes RI','https://kemkes.go.id',2);

INSERT OR IGNORE INTO edu_contents (id, slug, title, category, summary, body_md, source_name, source_url, status, published_at)
VALUES ('art-hpv-2026','imunisasi-hpv-2026-perluasan-untuk-anak-laki-laki','Imunisasi HPV 2026: Kini Mulai untuk Anak Laki-Laki','imunisasi','Imunisasi HPV gratis melindungi anak dari kanker akibat virus HPV. Program nasional untuk anak perempuan berjalan sejak 2023; pada 2026 perluasan untuk anak laki-laki dimulai bertahap di tiga provinsi.','Human Papillomavirus (HPV) adalah virus yang dapat menyebabkan kanker leher rahim pada perempuan serta kanker anus, kanker penis, dan kanker mulut-tenggorokan pada laki-laki dan perempuan. Cara paling efektif mencegahnya adalah imunisasi sebelum seseorang terpapar virus, yaitu pada usia anak sekolah.

Di Indonesia, imunisasi HPV diberikan gratis melalui Bulan Imunisasi Anak Sekolah (BIAS) bagi anak perempuan kelas 5 SD atau usia sekitar 11 tahun, dan telah berjalan nasional sejak 2023. Sejak 2025, imunisasi HPV untuk anak di bawah 20 tahun cukup diberikan satu dosis, mengikuti rekomendasi WHO. Anak perempuan kelas 6 dan kelas 9 yang belum pernah menerima imunisasi HPV dapat memperoleh imunisasi kejar.

Kabar terbaru 2026: Kementerian Kesehatan mulai memperluas imunisasi HPV gratis untuk anak laki-laki usia 10–11 tahun atau kelas 5 SD, dimulai Agustus 2026 di tiga provinsi — DKI Jakarta, Daerah Istimewa Yogyakarta, dan Bali — dan akan diperluas bertahap ke provinsi lain pada 2027 dan 2028. Artinya, untuk saat ini anak laki-laki di Lampung belum menjadi sasaran program gratis ini; orang tua di Lampung tetap memastikan anak perempuannya menerima imunisasi HPV di sekolah atau puskesmas, dan mengikuti pengumuman Dinas Kesehatan bila perluasan tiba di Lampung.

Imunisasi HPV aman dan telah melalui kajian ilmiah serta direkomendasikan WHO dan Kemenkes. Bila anak Anda terlewat jadwal BIAS, tanyakan imunisasi kejar ke puskesmas terdekat.','Kementerian Kesehatan RI','https://kemkes.go.id/eng/kemenkes-perluas-imunisasi-hpv-cegah-kanker-sejak-dini','published','2026-11-25 01:27:00');
INSERT OR IGNORE INTO ai_sources (id, title, publisher, url, content_text, topic_tags, status)
VALUES ('src-art-hpv-2026','Imunisasi HPV 2026: Kini Mulai untuk Anak Laki-Laki','Kementerian Kesehatan RI','https://kemkes.go.id/eng/kemenkes-perluas-imunisasi-hpv-cegah-kanker-sejak-dini','Imunisasi HPV mencegah kanker akibat Human Papillomavirus, termasuk kanker leher rahim, kanker anus, kanker penis, dan kanker orofaring. Di Indonesia imunisasi HPV gratis diberikan melalui BIAS bagi anak perempuan kelas 5 SD (sekitar 11 tahun), nasional sejak 2023, dan sejak 2025 cukup satu dosis untuk anak di bawah 20 tahun mengikuti rekomendasi WHO. Imunisasi kejar tersedia bagi anak perempuan kelas 6 dan kelas 9 yang belum pernah menerima. Pada 2026 Kemenkes memulai perluasan untuk anak laki-laki usia 10 sampai 11 tahun di tiga provinsi: DKI Jakarta, Daerah Istimewa Yogyakarta, dan Bali, dimulai Agustus 2026, dengan perluasan bertahap ke provinsi lain pada 2027 dan 2028. Anak laki-laki di Lampung belum menjadi sasaran program gratis ini per 2026. Cakupan imunisasi HPV anak perempuan kelas 5 mencapai 90,8% pada 2025 menurut Kemenkes.','imunisasi, hpv, kanker, anak','active');
INSERT OR IGNORE INTO edu_references (id, content_id, title, publisher, url, sort_order) VALUES ('ref-art-hpv-2026-1','art-hpv-2026','Kemenkes Perluas Imunisasi HPV, Cegah Kanker Sejak Dini','Kementerian Kesehatan RI','https://kemkes.go.id/eng/kemenkes-perluas-imunisasi-hpv-cegah-kanker-sejak-dini',1);
INSERT OR IGNORE INTO edu_references (id, content_id, title, publisher, url, sort_order) VALUES ('ref-art-hpv-2026-2','art-hpv-2026','Jadwal imunisasi anak — Kemenkes RI','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id',2);

INSERT OR IGNORE INTO edu_contents (id, slug, title, category, summary, body_md, source_name, source_url, status, published_at)
VALUES ('art-stunting','cegah-stunting-sejak-1000-hari-pertama','Cegah Stunting Sejak 1000 Hari Pertama Kehidupan','ibu-anak','Stunting di Lampung tercatat 15,9% (SSGI 2024). Masa terpenting untuk mencegahnya adalah 1000 hari pertama kehidupan: sejak kehamilan sampai anak berusia dua tahun.','Stunting adalah kondisi gagal tumbuh pada anak akibat kekurangan gizi kronis dan infeksi berulang, ditandai tinggi badan lebih pendek dari standar usianya. Menurut Survei Status Gizi Indonesia (SSGI) 2024, prevalensi stunting di Lampung adalah 15,9%. Stunting berdampak panjang pada perkembangan otak, prestasi belajar, dan risiko penyakit tidak menular di masa dewasa.

Periode penentu adalah 1000 hari pertama kehidupan: sejak masa kehamilan hingga anak berusia dua tahun. Pada masa ini kebutuhan gizi ibu dan anak harus terpenuhi: ibu hamil memeriksakan kehamilan minimal 6 kali, mengonsumsi tablet tambah darah, dan makan bergizi seimbang; bayi memperoleh ASI eksklusif 6 bulan; setelahnya MPASI bergizi dengan protein hewani sambil ASI diteruskan hingga dua tahun.

Pantau pertumbuhan anak setiap bulan di posyandu: berat dan tinggi badan diukur dan dicatat pada kurva pertumbuhan. Tanda yang perlu diwaspadai adalah berat badan tidak naik dalam dua bulan berturut-turut atau garis pertumbuhan mendatar — segera konsultasikan ke puskesmas agar penyebabnya dicari dan ditangani sejak dini.

Platform ini membantu orang tua mencatat pengukuran anak dan menilai status pertumbuhannya berdasarkan standar WHO yang dipakai Kemenkes, serta mengingatkan jadwal imunisasi. Penilaian di aplikasi bersifat pemantauan awal; penilaian klinis dan intervensi gizi tetap dilakukan tenaga kesehatan.','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id','published','2026-11-25 01:26:00');
INSERT OR IGNORE INTO ai_sources (id, title, publisher, url, content_text, topic_tags, status)
VALUES ('src-art-stunting','Cegah Stunting Sejak 1000 Hari Pertama Kehidupan','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id','Stunting adalah gagal tumbuh akibat kekurangan gizi kronis dan infeksi berulang; prevalensi di Lampung 15,9% menurut SSGI 2024. Masa penentu pencegahan adalah 1000 hari pertama kehidupan, sejak kehamilan sampai anak berusia dua tahun. Ibu hamil perlu periksa kehamilan minimal 6 kali, tablet tambah darah, dan gizi seimbang. Bayi perlu ASI eksklusif 6 bulan, lalu MPASI bergizi dengan protein hewani sambil ASI diteruskan hingga dua tahun. Pertumbuhan dipantau setiap bulan di posyandu; berat badan tidak naik dua bulan berturut-turut adalah tanda waspada yang perlu konsultasi ke puskesmas.','stunting, anak, gizi, ibu hamil','active');
INSERT OR IGNORE INTO edu_references (id, content_id, title, publisher, url, sort_order) VALUES ('ref-art-stunting-1','art-stunting','Cegah stunting — materi edukasi Kemenkes RI','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id',1);
INSERT OR IGNORE INTO edu_references (id, content_id, title, publisher, url, sort_order) VALUES ('ref-art-stunting-2','art-stunting','Survei Status Gizi Indonesia (SSGI) 2024','Kementerian Kesehatan RI','https://kemkes.go.id',2);

INSERT OR IGNORE INTO edu_contents (id, slug, title, category, summary, body_md, source_name, source_url, status, published_at)
VALUES ('art-anc','pemeriksaan-kehamilan-6-kali-selama-hamil','Pemeriksaan Kehamilan: Enam Kali Selama Masa Hamil','ibu-anak','Ibu hamil dianjurkan memeriksakan kehamilan minimal 6 kali. Di Lampung, cakupan kunjungan lengkap K6 baru mencapai 78,3% menurut Profil Kesehatan 2023 — masih banyak ibu yang perlu dibantu memenuhinya.','Pemeriksaan kehamilan (antenatal care) bertujuan memastikan ibu dan janin sehat serta mendeteksi risiko sejak dini. Sesuai ketentuan Kementerian Kesehatan, ibu hamil memeriksakan kehamilan minimal 6 kali selama masa kehamilan, dengan sebagian kunjungan dilakukan oleh dokter termasuk pemeriksaan USG.

Pada setiap kunjungan, tenaga kesehatan memeriksa tekanan darah, berat badan, tinggi fundus rahim, dan detak jantung janin; memberikan tablet tambah darah; serta memeriksa laboratorium dasar seperti hemoglobin dan golongan darah. Ibu juga mendapat edukasi tanda bahaya kehamilan.

Menurut Profil Kesehatan Provinsi Lampung 2023, cakupan kunjungan kehamilan lengkap (K6) di Lampung adalah 78,3% — artinya sekitar satu dari lima ibu hamil belum memeriksakan kehamilannya secara lengkap. Pemeriksaan kehamilan tersedia di puskesmas, pustu, praktik bidan, dan rumah sakit.

Segera ke fasilitas kesehatan dan jangan menunggu jadwal bila muncul tanda bahaya: perdarahan, nyeri perut hebat, sakit kepala hebat disertai pandangan kabur, bengkak pada wajah dan tangan, demam tinggi, keluar cairan ketuban sebelum waktunya, atau gerakan janin berkurang. Platform ini membantu mencatat jadwal kunjungan dan mengingatkan kunjungan berikutnya; pencatatan resmi tetap pada Buku KIA dan rekam medis fasilitas kesehatan.','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id','published','2026-11-25 01:25:00');
INSERT OR IGNORE INTO ai_sources (id, title, publisher, url, content_text, topic_tags, status)
VALUES ('src-art-anc','Pemeriksaan Kehamilan: Enam Kali Selama Masa Hamil','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id','Ibu hamil dianjurkan memeriksakan kehamilan minimal 6 kali selama masa kehamilan menurut Kemenkes, dengan sebagian kunjungan oleh dokter termasuk USG. Cakupan kunjungan lengkap K6 di Lampung adalah 78,3% menurut Profil Kesehatan Provinsi Lampung 2023. Pemeriksaan meliputi tekanan darah, berat badan, tinggi fundus, detak jantung janin, tablet tambah darah, dan laboratorium dasar. Tanda bahaya kehamilan yang harus segera ke fasilitas kesehatan: perdarahan, nyeri perut hebat, sakit kepala hebat dan pandangan kabur, bengkak wajah dan tangan, demam tinggi, ketuban pecah dini, gerakan janin berkurang. Pemeriksaan tersedia di puskesmas, pustu, praktik bidan, dan rumah sakit.','kehamilan, ibu hamil, anc, kia','active');
INSERT OR IGNORE INTO edu_references (id, content_id, title, publisher, url, sort_order) VALUES ('ref-art-anc-1','art-anc','Pemeriksaan kehamilan dan Buku KIA — Kemenkes RI','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id',1);
