INSERT OR IGNORE INTO edu_contents (id, slug, title, category, summary, body_md, source_name, source_url, status, published_at)
VALUES ('art-tb','tuberkulosis-batuk-lebih-dari-dua-minggu','Tuberkulosis: Waspada Batuk Lebih dari Dua Minggu','tb','Tuberkulosis (TB) menular lewat udara dan dapat disembuhkan dengan pengobatan teratur. Batuk lebih dari dua minggu adalah tanda utama yang tidak boleh dibiarkan.','Tuberkulosis (TB) adalah penyakit menular yang disebabkan bakteri Mycobacterium tuberculosis dan paling sering menyerang paru-paru. Indonesia termasuk negara dengan beban TB tinggi di dunia. TB menular melalui percikan dahak ketika penderita batuk atau bersin, terutama di ruangan tertutup yang kurang ventilasi.

Tanda utama TB paru adalah batuk berdahak selama dua minggu atau lebih. Tanda lain meliputi batuk berdarah, nyeri dada, sesak, demam dan berkeringat malam tanpa aktivitas, nafsu makan menurun, serta berat badan turun. Bila Anda atau keluarga mengalami batuk lebih dari dua minggu, segera periksa ke puskesmas. Pemeriksaan dahak dan pengobatan TB di fasilitas kesehatan pemerintah diberikan gratis melalui program TB nasional.

TB dapat disembuhkan dengan obat anti-tuberkulosis (OAT) yang diminum teratur selama minimal 6 bulan tanpa putus. Menghentikan obat sebelum tuntas berbahaya karena kuman dapat menjadi kebal obat dan penyakit lebih sulit diobati. Selama pengobatan, terapkan etika batuk, gunakan masker, buka jendela rumah agar sinar matahari dan udara segar masuk, dan jangan meludah sembarangan.

Keluarga yang tinggal serumah dengan penderita, terutama anak-anak, perlu diperiksa dan mungkin mendapat terapi pencegahan sesuai anjuran dokter. Jangan menunda pemeriksaan karena stigma — TB adalah penyakit yang dapat disembuhkan, dan semakin cepat ditemukan semakin kecil risiko menulari orang terdekat.','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id','published','2026-11-25 01:24:00');
INSERT OR IGNORE INTO ai_sources (id, title, publisher, url, content_text, topic_tags, status)
VALUES ('src-art-tb','Tuberkulosis: Waspada Batuk Lebih dari Dua Minggu','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id','Tuberkulosis (TB) disebabkan bakteri Mycobacterium tuberculosis, menular lewat percikan dahak saat batuk atau bersin. Tanda utama TB paru: batuk berdahak dua minggu atau lebih; tanda lain: batuk berdarah, nyeri dada, demam dan keringat malam, nafsu makan dan berat badan menurun. Batuk lebih dari dua minggu harus diperiksa ke puskesmas; pemeriksaan dahak dan pengobatan TB gratis di fasilitas kesehatan pemerintah. TB disembuhkan dengan obat anti-tuberkulosis (OAT) teratur minimal 6 bulan tanpa putus; berhenti sebelum tuntas dapat membuat kuman kebal obat. Kontak serumah terutama anak perlu diperiksa dan mungkin mendapat terapi pencegahan dari dokter.','tuberkulosis, tb, batuk, menular','active');
