INSERT OR IGNORE INTO edu_contents (id, slug, title, category, summary, body_md, source_name, source_url, status, published_at)
VALUES ('art-dbd','demam-berdarah-cegah-dengan-3m-plus','Demam Berdarah: Cegah dengan 3M Plus','lingkungan','Demam berdarah dengue ditularkan nyamuk Aedes aegypti yang berkembang biak di genangan air bersih sekitar rumah. Pemberantasan sarang nyamuk dengan 3M Plus adalah cara paling efektif mencegahnya.','Demam berdarah dengue (DBD) adalah penyakit akibat virus dengue yang ditularkan melalui gigitan nyamuk Aedes aegypti. Nyamuk ini aktif menggigit pada pagi dan sore hari dan berkembang biak di genangan air bersih: bak mandi, ember, vas bunga, talang air, hingga tutup botol berisi air hujan. Musim hujan meningkatkan risikonya, termasuk di Lampung.

Pencegahan paling efektif adalah Pemberantasan Sarang Nyamuk dengan 3M Plus: Menguras tempat penampungan air minimal seminggu sekali, Menutup rapat penampungan air, dan Mendaur ulang atau mengubur barang bekas yang dapat menampung air. Langkah Plus antara lain memakai larvasida pada penampungan yang sulit dikuras, memelihara ikan pemakan jentik, memakai kelambu dan obat nyamuk, serta menanam tanaman pengusir nyamuk. Gerakan satu rumah satu juru pemantau jentik (jumantik) membantu memastikan tidak ada jentik di rumah.

Kenali gejalanya: demam tinggi mendadak 2–7 hari, nyeri otot dan sendi, nyeri di belakang mata, mual, dan muncul bintik merah pada kulit. Segera ke IGD bila muncul tanda bahaya: nyeri perut hebat, muntah terus-menerus, perdarahan dari gusi atau hidung, muntah darah, lemas, atau gelisah. DBD dapat memburuk dengan cepat, terutama pada anak.

Tidak ada obat khusus untuk virus dengue; penanganan berfokus pada cairan dan pemantauan di fasilitas kesehatan. Karena itu pencegahan sarang nyamuk dan kecepatan datang ke fasilitas kesehatan saat bergejala adalah kunci.','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id','published','2026-11-25 01:23:00');
INSERT OR IGNORE INTO ai_sources (id, title, publisher, url, content_text, topic_tags, status)
VALUES ('src-art-dbd','Demam Berdarah: Cegah dengan 3M Plus','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id','Demam berdarah dengue (DBD) ditularkan nyamuk Aedes aegypti yang berkembang biak di genangan air bersih dan aktif pagi serta sore hari. Pencegahan utama adalah 3M Plus: Menguras penampungan air minimal seminggu sekali, Menutup rapat penampungan air, Mendaur ulang atau mengubur barang bekas penampung air; Plus larvasida, ikan pemakan jentik, kelambu, dan obat nyamuk. Gejala: demam tinggi mendadak 2 sampai 7 hari, nyeri otot dan sendi, nyeri belakang mata, bintik merah kulit. Tanda bahaya yang harus segera ke IGD: nyeri perut hebat, muntah terus, perdarahan gusi atau hidung, muntah darah, lemas, gelisah. Tidak ada obat khusus virus dengue; penanganan fokus pada cairan dan pemantauan di fasilitas kesehatan.','dbd, dengue, nyamuk, lingkungan','active');
INSERT OR IGNORE INTO edu_references (id, content_id, title, publisher, url, sort_order) VALUES ('ref-art-dbd-1','art-dbd','Demam berdarah dengue — materi edukasi Kemenkes RI','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id',1);
INSERT OR IGNORE INTO edu_references (id, content_id, title, publisher, url, sort_order) VALUES ('ref-art-dbd-2','art-dbd','Pemberantasan Sarang Nyamuk 3M Plus','Kementerian Kesehatan RI','https://kemkes.go.id',2);

INSERT OR IGNORE INTO edu_contents (id, slug, title, category, summary, body_md, source_name, source_url, status, published_at)
VALUES ('art-jiwa','kesehatan-jiwa-mengenali-stres-dan-mencari-bantuan','Kesehatan Jiwa: Mengenali Stres dan Berani Mencari Bantuan','jiwa','Stres adalah respons wajar, tetapi stres berkepanjangan yang mengganggu tidur, pekerjaan, dan hubungan perlu ditangani. Mencari bantuan adalah tanda kekuatan, bukan kelemahan.','Kesehatan jiwa sama pentingnya dengan kesehatan fisik. Stres adalah respons alami tubuh terhadap tekanan, namun stres yang berkepanjangan dapat berkembang menjadi gangguan kecemasan atau depresi dan memengaruhi kesehatan fisik.

Tanda-tanda stres dan kesehatan jiwa yang sedang menurun antara lain: sulit tidur atau tidur berlebihan, kehilangan minat pada hal yang biasanya disukai, mudah marah atau menangis, sulit berkonsentrasi, menarik diri dari keluarga dan teman, serta keluhan fisik berulang tanpa sebab jelas seperti sakit kepala atau nyeri lambung.

Langkah awal yang dapat dilakukan: tidur cukup dan teratur, tetap beraktivitas fisik, batasi kafein dan hindari alkohol, luangkan waktu untuk hobi, dan ceritakan beban pikiran kepada orang yang dipercaya. Teknik napas dalam dan relaksasi sederhana membantu meredakan ketegangan sesaat.

Jangan ragu mencari bantuan profesional. Layanan kesehatan jiwa tersedia di banyak puskesmas dan rumah sakit, dan Anda dapat memulainya dengan berkonsultasi ke dokter umum atau psikolog. Bila Anda atau orang terdekat memiliki pikiran untuk menyakiti diri, segera hubungi layanan darurat 119 atau datang ke IGD terdekat — keselamatan adalah prioritas dan bantuan tersedia. Mendampingi teman atau keluarga yang sedang berat dengan mendengarkan tanpa menghakimi juga sangat berarti.','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id','published','2026-11-25 01:22:00');
INSERT OR IGNORE INTO ai_sources (id, title, publisher, url, content_text, topic_tags, status)
VALUES ('src-art-jiwa','Kesehatan Jiwa: Mengenali Stres dan Berani Mencari Bantuan','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id','Stres berkepanjangan dapat berkembang menjadi kecemasan atau depresi. Tanda kesehatan jiwa menurun: sulit tidur atau tidur berlebihan, kehilangan minat, mudah marah atau menangis, sulit konsentrasi, menarik diri, keluhan fisik berulang tanpa sebab jelas. Langkah awal: tidur cukup dan teratur, aktivitas fisik, batasi kafein dan hindari alkohol, hobi, bercerita kepada orang terpercaya, teknik napas dalam. Bantuan profesional tersedia di puskesmas dan rumah sakit melalui dokter umum atau psikolog. Pikiran menyakiti diri adalah keadaan darurat: hubungi 119 atau ke IGD terdekat.','kesehatan jiwa, stres, depresi, kecemasan','active');
INSERT OR IGNORE INTO edu_references (id, content_id, title, publisher, url, sort_order) VALUES ('ref-art-jiwa-1','art-jiwa','Kesehatan jiwa — materi edukasi Kemenkes RI','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id',1);
INSERT OR IGNORE INTO edu_references (id, content_id, title, publisher, url, sort_order) VALUES ('ref-art-jiwa-2','art-jiwa','Mental health — WHO','Organisasi Kesehatan Dunia (WHO)','https://www.who.int',2);

INSERT OR IGNORE INTO edu_contents (id, slug, title, category, summary, body_md, source_name, source_url, status, published_at)
VALUES ('art-ggl','gula-garam-lemak-batas-harian-yang-dianjurkan','Gula, Garam, Lemak: Batas Harian yang Dianjurkan','gizi','Kemenkes menganjurkan konsumsi per orang per hari: gula maksimal 4 sendok makan, garam 1 sendok teh, dan lemak 5 sendok makan. Angka sederhana ini membantu mencegah hipertensi, diabetes, dan penyakit jantung.','Sebagian besar penyakit tidak menular berawal dari pola makan yang berlebihan gula, garam, dan lemak (GGL) dalam jangka panjang. Kementerian Kesehatan memberikan patokan yang mudah diingat untuk setiap orang per hari: gula maksimal 4 sendok makan (sekitar 50 gram), garam maksimal 1 sendok teh (sekitar 5 gram), dan lemak atau minyak maksimal 5 sendok makan (sekitar 67 gram).

Patokan ini mudah terlampaui tanpa disadari. Satu botol minuman manis kemasan dapat mengandung gula mendekati atau melebihi jatah sehari. Garam tersembunyi banyak terdapat pada mie instan, makanan olahan, saus, kecap, dan makanan cepat saji. Lemak berlebih datang dari gorengan, santan kental, dan lemak daging.

Cara praktis mengurangi GGL: biasakan membaca label kemasan dan pilih produk dengan gula, garam, dan lemak lebih rendah; kurangi gula pada minuman buatan sendiri secara bertahap; perbanyak masak di rumah dengan bumbu alami; pilih cara memasak kukus, rebus, atau panggang lebih sering daripada goreng; dan seimbangkan piring makan mengikuti pedoman Isi Piringku dengan setengah piring sayur dan buah.

Kebutuhan setiap orang dapat berbeda, misalnya pada penderita hipertensi, diabetes, atau penyakit ginjal yang memerlukan batas lebih ketat dari dokter atau ahli gizi. Gunakan patokan GGL sebagai titik awal, dan konsultasikan kebutuhan khusus Anda di puskesmas.','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id','published','2026-11-25 01:21:00');
INSERT OR IGNORE INTO ai_sources (id, title, publisher, url, content_text, topic_tags, status)
VALUES ('src-art-ggl','Gula, Garam, Lemak: Batas Harian yang Dianjurkan','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id','Kemenkes menganjurkan batas konsumsi per orang per hari: gula maksimal 4 sendok makan (sekitar 50 gram), garam maksimal 1 sendok teh (sekitar 5 gram), lemak atau minyak maksimal 5 sendok makan (sekitar 67 gram). Gula berlebih banyak pada minuman manis kemasan; garam tersembunyi pada mie instan, makanan olahan, saus, dan makanan cepat saji; lemak berlebih dari gorengan dan santan kental. Cara mengurangi: baca label kemasan, kurangi gula bertahap, masak di rumah, pilih kukus rebus panggang, ikuti Isi Piringku. Penderita hipertensi, diabetes, atau penyakit ginjal mungkin perlu batas lebih ketat dari dokter atau ahli gizi.','gizi, gula, garam, lemak, ggl','active');
INSERT OR IGNORE INTO edu_references (id, content_id, title, publisher, url, sort_order) VALUES ('ref-art-ggl-1','art-ggl','Batas konsumsi gula, garam, lemak — Kemenkes RI','Kementerian Kesehatan RI','https://ayosehat.kemkes.go.id',1);
