INSERT OR IGNORE INTO edu_quizzes (id, content_id, title, questions_json, status)
VALUES ('quiz-ckg-2026', 'art-ckg-2026', 'Kuis Cek Kesehatan Gratis', '[{"question_text": "Sejak kapan program Cek Kesehatan Gratis (CKG) berjalan?", "options": ["10 Februari 2025", "1 Januari 2024", "17 Agustus 2025", "10 Februari 2023"], "correct_index": 0, "explanation": "CKG mulai berjalan pada 10 Februari 2025 di puskesmas seluruh Indonesia."}, {"question_text": "Berapa target penduduk yang menerima CKG pada 2026 menurut Kemenkes?", "options": ["10%", "25%", "46%", "90%"], "correct_index": 2, "explanation": "Target 2026 adalah 46% penduduk, naik dari capaian 24,9% pada tahun pertama."}, {"question_text": "Apa perubahan penting CKG mulai 2026?", "options": ["Pemeriksaan menjadi berbayar", "Hasil pemeriksaan ditindaklanjuti pengobatan gratis untuk kondisi tertentu", "CKG hanya untuk lansia", "CKG hanya di rumah sakit"], "correct_index": 1, "explanation": "Mulai 2026 hasil CKG ditindaklanjuti, antara lain pengobatan gratis bagi peserta dengan hipertensi dan diabetes."}, {"question_text": "Selain di puskesmas, CKG 2026 juga diperluas ke mana?", "options": ["Hanya mal", "Pustu, posyandu, tempat kerja, dan komunitas", "Hanya luar negeri", "Tidak diperluas"], "correct_index": 1, "explanation": "Layanan diperluas ke puskesmas pembantu, posyandu, fasilitas kesehatan lain, perkantoran, dan komunitas."}, {"question_text": "Apa sifat hasil CKG?", "options": ["Diagnosis akhir yang pasti", "Skrining dan pemeriksaan awal yang perlu ditindaklanjuti bila ada kelainan", "Pengganti rekam medis", "Tidak perlu ditindaklanjuti"], "correct_index": 1, "explanation": "Hasil CKG adalah skrining dan pemeriksaan awal; kelainan yang ditemukan diarahkan ke pemeriksaan dan pengobatan lanjutan."}]', 'published');

INSERT OR IGNORE INTO edu_quizzes (id, content_id, title, questions_json, status)
VALUES ('quiz-ggl', 'art-ggl', 'Kuis Gula, Garam, Lemak', '[{"question_text": "Berapa batas konsumsi gula per orang per hari menurut Kemenkes?", "options": ["10 sendok makan", "4 sendok makan", "1 sendok makan", "Tidak ada batas"], "correct_index": 1, "explanation": "Gula maksimal 4 sendok makan (sekitar 50 gram) per orang per hari."}, {"question_text": "Berapa batas konsumsi garam per hari?", "options": ["1 sendok makan", "3 sendok teh", "1 sendok teh (sekitar 5 gram)", "5 gram per sekali makan"], "correct_index": 2, "explanation": "Garam maksimal 1 sendok teh atau sekitar 5 gram per hari."}, {"question_text": "Berapa batas konsumsi lemak atau minyak per hari?", "options": ["5 sendok makan", "10 sendok makan", "1 sendok teh", "Tidak perlu dibatasi"], "correct_index": 0, "explanation": "Lemak atau minyak maksimal 5 sendok makan (sekitar 67 gram) per hari."}, {"question_text": "Makanan apa yang banyak mengandung garam tersembunyi?", "options": ["Sayur segar", "Buah potong", "Mie instan dan makanan olahan", "Air putih"], "correct_index": 2, "explanation": "Mie instan, makanan olahan, saus, dan makanan cepat saji mengandung garam tersembunyi yang tinggi."}, {"question_text": "Cara memasak apa yang lebih dianjurkan untuk mengurangi lemak?", "options": ["Menggoreng rendam", "Kukus, rebus, atau panggang", "Menambah santan kental", "Menggoreng dua kali"], "correct_index": 1, "explanation": "Kukus, rebus, dan panggang menggunakan jauh lebih sedikit minyak daripada menggoreng."}]', 'published');
